2605: # { Transport ('output-schema' | 'prompt-only'); Basis } for the identity's endpoint;
2606: # 'prompt-only' is the safe default for an endpoint caps-v1 does not declare (a
2607: # json_schema response format it may reject would fail the whole run).
2608: function Get-SchemaTransport {
2609:     param($Identity)
2610:     $hostName = [string]$Identity.HostName
2611:     if ($hostName -and $script:EffortCaps.ContainsKey($hostName)) {
2612:         return [pscustomobject]@{ Transport = $script:EffortCaps[$hostName].SchemaTransport; Basis = "$($script:EffortCapsVersion): $hostName" }
2613:     }
2614:     $label = if ($hostName) { $hostName } else { 'unknown-host' }
2615:     return [pscustomobject]@{ Transport = 'prompt-only'; Basis = "default for an endpoint $($script:EffortCapsVersion) does not declare: $label" }
2616: }
2617: 
