2977: # ----------------------------------------------------------------------------- engines
2978: #
2979: # The CLI that carries a consultation (0.4.0, ROADMAP R10). One row per engine; `codex` is
2980: # the default and its path through codex-consult.ps1 is the 0.3.0 one. Every other engine is
2981: # driven through the same adapter interface (the Adapter functions named in its row), so a
2982: # further engine (e.g. `claude`) is one more row plus its adapter functions:
2983: #   Argv        the argv of a turn (New-AgyArgv)
2984: #   Stdin       the bytes written to the turn's stdin (ConvertTo-AgyStdin)
2985: #   Events      the event-stream parser (Read-AgyEvents) -> a normalized turn record
2986: #   Outcome     the failure rules of a turn (Get-AgyTurnOutcome)
2987: #   Credential  the sign-in check of the preflight (Get-AgyModelsStatus)
2988: # Row fields: Name, Label (handoff header / author), Prefix (handoff file names
2989: # NN-<prefix>-<slug>.*), Command (first word of the ledger `command`), ExeEnv (launcher
2990: # override), LauncherNames (PATH lookup, in order), Modes, DefaultMode ('' = automatic:
2991: # fork when a parent exists), Sandboxes, Transports (-SchemaTransport values), HostName
2992: # (caps-v1 key), CompatString (the provider fingerprint's input), DefaultProvider (the
2993: # lineage label without -Provider), ModelExample.
2994: #
2995: #   agy   Google's Antigravity CLI: `agy -p= --input-format stream-json --output-format
2996: #         stream-json --model <m> [--json-schema <schema>] --print-timeout 0 --sandbox
2997: #         --disable-slash-commands [--conversation <thread>] [--effort <v>]`, the prompt as
2998: #         ONE NDJSON line on stdin, the reply = the LAST (and only) `result` event's
2999: #         structured_output (never its `response` text when structured_output is there).
3000: #         Read-only is NOT enforced by agy (--sandbox restricts the terminal only): the
3001: #         bridge's tree check fails a run that changed the working tree (tracked or
3002: #         untracked files) or the collab directory; gitignored paths, submodules and files
3003: #         outside the repository stay unmonitored.
3004: $script:EngineNames = @('codex', 'agy')
3005: $script:Engines = @{
3006:     'codex' = [pscustomobject]@{
3007:         Name = 'codex'; Label = 'Codex'; Prefix = 'codex'; Command = 'codex'; ExeEnv = 'CODEX_CONSULT_EXE'
3008:         LauncherNames = $(if ($script:OnWindows) { @('codex.exe', 'codex.cmd', 'codex.bat', 'codex') } else { @('codex') })
3009:         Modes = @('new', 'resume', 'fork'); DefaultMode = ''; Sandboxes = @('read-only', 'workspace-write')
3010:         Transports = @('output-schema', 'prompt-only'); HostName = ''; CompatString = ''; DefaultProvider = ''; ModelExample = 'gpt-5.1'
3011:         Adapter = $null
3012:     }
3013:     'agy'   = [pscustomobject]@{
3014:         Name = 'agy'; Label = 'Gemini (agy)'; Prefix = 'agy'; Command = 'agy'; ExeEnv = 'CODEX_CONSULT_AGY_EXE'
3015:         LauncherNames = $(if ($script:OnWindows) { @('agy.exe', 'agy.cmd', 'agy.bat', 'agy') } else { @('agy') })
3016:         Modes = @('new', 'resume'); DefaultMode = 'new'; Sandboxes = @('read-only')
3017:         Transports = @('native', 'prompt-only'); HostName = 'engine:agy'; CompatString = 'cc-engine-v1|agy'; DefaultProvider = 'gemini'; ModelExample = 'gemini-3.8-flash-high'
3018:         Adapter = [pscustomobject]@{ Argv = 'New-AgyArgv'; Stdin = 'ConvertTo-AgyStdin'; Events = 'Read-AgyEvents'; Outcome = 'Get-AgyTurnOutcome'; Credential = 'Get-AgyModelsStatus' }
3019:     }
3020: }
