3065: # The harness string of an engine run (reviewer.harness): agy has no --version flag (the CLI
3066: # rejects unknown flags), so the version comes from the launcher's file metadata when it
3067: # carries one: "agy-cli <version>" or "agy-cli (version unknown)". Nothing is started.
3068: function Get-EngineHarness {
3069:     param([string]$Engine, [string]$Launcher)
3070:     $ver = ''
3071:     if ($Launcher) {
3072:         try { $ver = [string](Get-Item -LiteralPath $Launcher -ErrorAction Stop).VersionInfo.ProductVersion } catch { $ver = '' }
3073:     }
3074:     if ($ver -and $ver.Trim()) { return "$Engine-cli $($ver.Trim())" }
3075:     return "$Engine-cli (version unknown)"
3076: }
