3078: # `agy models` with a timeout (a network round-trip, usually ~2 s but observed at 1.7-15+ s,
3079: # hence 45 s): exit 0 and at least one "<id><TAB><name>" line -> ok "signed in (N models)";
3080: # output mentioning login / sign in / auth / unauthenticated -> missing; anything else (and a
3081: # timeout) -> unknown. stdout and stderr are read as UTF-8. { State; Reason; Detail } like
3082: # Get-CodexLoginStatus.
3083: $script:AgyModelsTimeoutSec = 45
3084: function Get-AgyModelsStatus {
3085:     param([string]$Launcher, [int]$TimeoutSec = 45)
3086:     if (-not $Launcher) { return (New-CredentialResult 'missing' 'agy CLI not found on PATH') }
3087:     $p = $null
3088:     try {
3089:         $psi = New-Object System.Diagnostics.ProcessStartInfo
3090:         $psi.FileName = $Launcher
3091:         $psi.Arguments = 'models'
3092:         $psi.UseShellExecute = $false
3093:         $psi.CreateNoWindow = $true
3094:         $psi.RedirectStandardInput = $true
3095:         $psi.RedirectStandardOutput = $true
3096:         $psi.RedirectStandardError = $true
3097:         $psi.StandardOutputEncoding = $script:Utf8NoBom
3098:         $psi.StandardErrorEncoding = $script:Utf8NoBom
3099:         $p = [System.Diagnostics.Process]::Start($psi)
3100:     } catch {
3101:         return (New-CredentialResult 'unknown' "``agy models`` could not be started ($(ConvertTo-OneLine $_.Exception.Message))")
3102:     }
3103:     try {
3104:         try { $p.StandardInput.Close() } catch { }
3105:         $outTask = $p.StandardOutput.ReadToEndAsync()
3106:         $errTask = $p.StandardError.ReadToEndAsync()
3107:         if (-not $p.WaitForExit($TimeoutSec * 1000)) {
3108:             $null = Stop-ProcessTree -Process $p
3109:             return (New-CredentialResult 'unknown' "``agy models`` did not finish within $TimeoutSec s")
3110:         }
3111:         $p.WaitForExit()
3112:         $null = $outTask.Wait(5000)
3113:         $null = $errTask.Wait(5000)
3114:         $outLines = @(([string]$outTask.Result) -split "`r?`n" | Where-Object { $_ -and $_.Trim() })
3115:         $allLines = @((([string]$outTask.Result) + "`n" + ([string]$errTask.Result)) -split "`r?`n" | ForEach-Object { $_.Trim() } | Where-Object { $_ })
3116:         $models = @($outLines | Where-Object { $_ -match '^\S+\t' })
3117:         if ($p.ExitCode -eq 0 -and $models.Count -ge 1) { return (New-CredentialResult 'ok' "signed in ($($models.Count) models)") }
3118:         $authLine = @($allLines | Where-Object { $_ -match '(?i)log ?in|sign in|signed in|\bauth|unauthenticated' }) | Select-Object -First 1
3119:         if ($authLine) { return (New-CredentialResult 'missing' "``agy models``: $authLine") }
