3127: # Sign-in of an engine for the preflight and the listing. A missing launcher is always
3128: # missing ("agy CLI not found on PATH"). Then (wave 18, F13) the ledger short-circuit: when
3129: # $Health (Get-EndpointHealth of the engine's endpoint, read from THIS repository's ledgers)
3130: # holds a usable reply no older than 60 minutes (RecentUsable, consult clock), the sign-in is
3131: # evidenced - "ok: signed in (usable reply <m> min ago)" - and nothing is started (also with
3132: # -NoNetwork: it is a ledger read). The caller keeps the endpoint health's auth and quota rules
3133: # in front of it (Get-PreflightVerdict): a recorded auth failure or a usage limit still
3134: # refuses. -NoNetwork (the SessionStart hook): otherwise nothing is started - "not checked
3135: # (launcher present; run codex-providers.ps1)", State unknown, Reason "sign-in not checked".
3136: # Else the adapter's check (agy: `agy models`, 45 s - TEST HOOK
3137: # CODEX_CONSULT_TEST_LOGIN_TIMEOUT=<s> shortens it). $LoginCache: one check per launcher per
3138: # listing.
3139: function Get-EngineCredential {
3140:     param([string]$Engine, [string]$Launcher, [hashtable]$LoginCache = $null, [switch]$NoNetwork, [int]$TimeoutSec = 0, $Health = $null)
3141:     $spec = Get-EngineSpec -Name $Engine
3142:     if (-not $spec -or -not $spec.Adapter) { return (New-CredentialResult 'unknown' "no credential check for engine '$Engine'") }
3143:     if (-not $Launcher) { return (New-CredentialResult 'missing' "$($spec.Command) CLI not found on PATH") }
3144:     if ($Health -and $Health.PSObject.Properties['RecentUsable'] -and $Health.RecentUsable) {
3145:         return (New-CredentialResult 'ok' "signed in (usable reply $($Health.RecentUsable.AgeMinutes) min ago)")
3146:     }
3147:     if ($NoNetwork) { return [pscustomobject]@{ State = 'unknown'; Reason = 'sign-in not checked'; Detail = 'not checked (launcher present; run codex-providers.ps1)' } }
3148:     if ($TimeoutSec -le 0) {
3149:         $TimeoutSec = $script:AgyModelsTimeoutSec
3150:         $hook = ([string]$env:CODEX_CONSULT_TEST_LOGIN_TIMEOUT).Trim()
3151:         if ($hook -match '^[0-9]+$' -and [int]$hook -gt 0) { $TimeoutSec = [int]$hook }
3152:     }
3153:     $key = "engine:$Engine|$Launcher"
3154:     if ($LoginCache -and $LoginCache.ContainsKey($key)) { return $LoginCache[$key] }
3155:     $r = & $spec.Adapter.Credential -Launcher $Launcher -TimeoutSec $TimeoutSec
3156:     if ($LoginCache) { $LoginCache[$key] = $r }
3157:     return $r
3158: }
