3401: # Classes of a provider failure, tried in this order (case-insensitive). permission comes
3402: # first (0.4.0, agy F11: a tool the headless print mode cannot grant was auto-denied and
3403: # the turn produced nothing). capability comes next: "Your token plan does not support
3404: # response_format" is a capability rejection, not a quota one. auth matches whole words
3405: # only ("text authored by" is not auth). transport stays last. Google's wordings (the agy
3406: # engine): RESOURCE_EXHAUSTED -> quota, UNAUTHENTICATED / PERMISSION_DENIED / "not signed
3407: # in" -> auth, INVALID_ARGUMENT / "invalid model selection" -> capability, UNAVAILABLE /
3408: # DEADLINE_EXCEEDED -> transport.
3409: # A usage limit said in WORDS ($script:QuotaTextPattern: usage limit, quota, rate limit, ...)
3410: # is quota even under an auth status, and is tried right before auth: Kimi Code answers "403
3411: # Forbidden: You've reached your 5-hour usage limit..." (live ledger, 2026-09-26), which the
3412: # 403 must not turn into an auth failure - the preflight would refuse that endpoint for 24 h.
3413: $script:QuotaTextPattern = '(?i)usage[ _]limit|quota|rate[ _]limit|resource_exhausted|too many requests'
3414: $script:FailureClassPatterns = [ordered]@{
3415:     'permission' = '(?i)no output produced|auto-denied|permission that headless mode'
3416:     'capability' = '(?i)not supported|unsupported|does(?: not|n[''\u2019]t) support|do not support|feature_not_supported|json_schema|invalid_argument|invalid model selection|conflicts with --effort'
3417:     'auth'       = '(?i)\b40[13]\b|unauthori[sz]ed|forbidden|invalid[ _]api[ _]key|\bauthentication\b|\bauth\b|\bapi key\b|permission_denied|unauthenticated|not signed in|login required|sign in to'
3418:     'quota'      = '(?i)usage[ _]limit|quota|rate[ _]limit|\b429\b|insufficient balance|too many requests|credits? exhausted|credit balance|payment required|\b402\b|token plan|plan exhausted|billing|resource_exhausted|rate_limit_exceeded'
3419:     'transport'  = '(?i)timeout|timed out|connection|econn|enotfound|\bdns\b|\btls\b|certificate|\b50[234]\b|network|\bunavailable\b|deadline_exceeded'
3420: }
3421: $script:BuiltinOpenAiFingerprint = Get-Sha256Hex ($script:Utf8NoBom.GetBytes('cc-provider-v1|builtin:openai'))
3422: 
3423: # permission | capability | auth | quota | transport | unknown
3424: function Get-ProviderFailureClass {
3425:     param([string]$Message)
3426:     foreach ($k in $script:FailureClassPatterns.Keys) {
3427:         if ($k -eq 'auth' -and $Message -match $script:QuotaTextPattern) { return 'quota' }
3428:         if ($Message -match $script:FailureClassPatterns[$k]) { return $k }
3429:     }
3430:     return 'unknown'
3431: }
