3029: # The launcher of an engine: $Explicit (codex: -CodexExe; others: -EngineExe), then the
3030: # engine's ExeEnv variable, then its LauncherNames on PATH. An explicit launcher that does not
3031: # resolve is an error (never a silent fall-through to PATH); $null when none is found.
3032: function Resolve-EngineLauncher {
3033:     param([string]$Engine, [string]$Explicit = '')
3034:     if (-not $Engine -or $Engine -eq 'codex') { return (Resolve-CodexLauncher -Explicit $Explicit) }
3035:     $spec = Get-EngineSpec -Name $Engine
3036:     if (-not $spec) { return $null }
3037:     $sources = @(@{ value = $Explicit; label = '-EngineExe' }, @{ value = [Environment]::GetEnvironmentVariable($spec.ExeEnv); label = $spec.ExeEnv })
3038:     foreach ($source in $sources) {
3039:         $candidate = [string]$source.value
3040:         if ($candidate) {
3041:             if (Test-Path -LiteralPath $candidate) { return (Resolve-Path -LiteralPath $candidate).Path }
3042:             $cmd = Get-Command $candidate -CommandType Application -ErrorAction SilentlyContinue
3043:             if ($cmd) { return @($cmd)[0].Source }
3044:             Stop-WithError "$($source.label) '$candidate' is not a file and not an application on PATH."
3045:         }
3046:     }
3047:     foreach ($name in @($spec.LauncherNames)) {
3048:         $cmd = Get-Command $name -CommandType Application -ErrorAction SilentlyContinue
3049:         if ($cmd) { return @($cmd)[0].Source }
3050:     }
3051:     return $null
3052: }
