 511: # A TEST HOOK's milliseconds: "<ms>" for every run, or "<model>=<ms>[|<model>=<ms>...]" (with
 512: # "*=<ms>" for the other models) for the runs of $Model; 0 when unset or not for this model.
 513: function Get-TestHookMs {
 514:     param([string]$Value, [string]$Model)
 515:     if (-not $Value) { return 0 }
 516:     $pick = ''
 517:     foreach ($item in $Value.Split('|')) {
 518:         $eq = $item.IndexOf('=')
 519:         if ($eq -lt 0) { if ($item.Trim() -and -not $pick) { $pick = $item.Trim() }; continue }
 520:         $k = $item.Substring(0, $eq).Trim()
 521:         if ($k -ceq $Model) { $pick = $item.Substring($eq + 1).Trim(); break }
 522:         if ($k -eq '*') { $pick = $item.Substring($eq + 1).Trim() }
 523:     }
 524:     $ms = 0
 525:     if ([int]::TryParse($pick, [ref]$ms) -and $ms -gt 0) { return $ms }
 526:     return 0
 527: }
