 540: # ----------------------------------------------------------------------------- engine turns (agy)
 541: 
 542: # One more turn of a non-codex engine (the denial retry, the format repair) under the SAME
 543: # task lock and recovery record as the run: the record goes launching -> running (child pid,
 544: # start time, `events` = this turn's event stream) before the process is waited on; a timeout
 545: # kills the process tree, and survivors are recorded (state survivors) and keep the record.
 546: # Reads the run's $pendingRecord, $pendingPath, $engineLauncher, $engineName and $repoRoot.
 547: # { Exit (-1 unless it exited); Problem ('' or why the turn did not complete); Wall;
 548: # KeepPending; Stderr (UTF-8 text) }.
 549: function Invoke-EngineTurn {
 550:     param([string[]]$Argv, [string]$StdinText, [string]$EventsPath, [string]$StdinPath, [string]$StderrPath, [int]$Timeout, [string]$Note)
 551:     $t = [pscustomobject]@{ Exit = -1; Problem = ''; Wall = 0; KeepPending = $false; Stderr = '' }
 552:     Write-Utf8NoBom -Path $StdinPath -Text $StdinText
 553:     $watch = [System.Diagnostics.Stopwatch]::StartNew()
 554:     $pendingRecord.state = 'launching'
 555:     $pendingRecord.note = "$Note being started; its pid is not recorded yet"
 556:     try { Write-PendingFile -Path $pendingPath -Record $pendingRecord } catch {
 557:         $t.Problem = "could not write the recovery record ($(ConvertTo-OneLine $_.Exception.Message)); the turn was not started"
 558:         return $t
 559:     }
 560:     $proc = $null
 561:     try {
 562:         $proc = Start-Process -FilePath $engineLauncher -ArgumentList ((($Argv | ForEach-Object { ConvertTo-ProcArg $_ }) -join ' ')) `
 563:             -WorkingDirectory $repoRoot -NoNewWindow -PassThru `
 564:             -RedirectStandardOutput $EventsPath `
 565:             -RedirectStandardError $StderrPath `
 566:             -RedirectStandardInput $StdinPath
 567:     } catch {
 568:         $t.Problem = "could not start $engineName - $(ConvertTo-OneLine $_.Exception.Message)"
 569:     }
 570:     if ($proc) {
 571:         if ($script:LegacyPS) { try { $null = $proc.Handle } catch { } }
 572:         $registered = $true
 573:         try {
 574:             $pendingRecord.state = 'running'
 575:             $pendingRecord.child_pid = $proc.Id
 576:             $pendingRecord.child_start_time = [string](Get-ProcessStartIso -ProcessId $proc.Id)
 577:             $pendingRecord.note = $Note
 578:             $evRel = Get-RepoRelativePath -Root $repoRoot -Path $EventsPath
 579:             $pendingRecord.events = $(if ($evRel) { $evRel } else { $EventsPath })
 580:             Write-PendingFile -Path $pendingPath -Record $pendingRecord
 581:         } catch {
 582:             $registered = $false
 583:             $t.Problem = "could not register the $Note process ($(ConvertTo-OneLine $_.Exception.Message)); it was stopped"
 584:             # the record on disk still says launching: so does the one in memory
 585:             $pendingRecord.state = 'launching'; $pendingRecord.child_pid = $null; $pendingRecord.child_start_time = ''
 586:             $null = Stop-ProcessTree -Process $proc
 587:         }
 588:         if ($registered) {
 589:             if (-not $proc.WaitForExit($Timeout * 1000)) {
 590:                 $surv = Stop-ProcessTree -Process $proc   # [int[]]; never wrap in @()
 591:                 $t.Problem = "timeout after $Timeout s (process tree killed)"
 592:                 if ($surv.Count -gt 0) {
 593:                     $t.Problem = "timeout after $Timeout s (process tree killed; $($surv.Count) processes survived: pid $($surv -join ', '))"
 594:                     $t.KeepPending = $true
 595:                     try {
 596:                         $pendingRecord.state = 'survivors'
 597:                         $pendingRecord.survivors = [object[]]@(New-SurvivorEntries -Pids $surv)
 598:                         Write-PendingFile -Path $pendingPath -Record $pendingRecord
 599:                     } catch { }
 600:                 }
 601:             } else {
 602:                 $t.Exit = $proc.ExitCode
 603:             }
 604:         }
 605:     }
 606:     $watch.Stop()
 607:     $t.Wall = [math]::Round($watch.Elapsed.TotalSeconds, 1)
 608:     $t.Stderr = Read-SharedText -Path $StderrPath
 609:     return $t
 610: }
