 612: # The agy engine's read-only check (A17, widened in wave 18 - F09-1/F10-1): '' when nothing the
 613: # review must not touch changed during the run, else the reason - the working tree (tracked
 614: # or untracked files; the paths that changed), the collab directory (EVERY file under it,
 615: # recursively: every task's stores and handoffs - outside the tree fingerprint; the run's own
 616: # <task>/handoffs/NN-<prefix>-<slug>.* files and the .consult.* lock and recovery files
 617: # excepted), the brief, an artifact. The check cannot tell who changed a file, so the text
 618: # does not blame the reviewer (F09-3). Gitignored paths, submodules and files outside the
 619: # repository stay unmonitored (README "Engines", F12). $CollabShown: the collab directory as
 620: # shown in front of its paths ('.collab/' inside the repository, '' otherwise).
 621: function Get-EngineTreeProblem {
 622:     param($RevBefore, $RevAfter, [bool]$BriefChanged, [string[]]$ChangedArtifacts, [hashtable]$CollabBefore, [hashtable]$CollabAfter, [string[]]$OwnPrefixes, [string]$Engine, [string]$CollabShown = '')
 623:     $cut = { param([string[]]$Names) $n = @($Names); $list = (@($n | Select-Object -First 5) -join ', '); if ($n.Count -gt 5) { $list += ', ...' }; "$($n.Count) file$(if ($n.Count -ne 1) { 's' }): $list" }
 624:     $why = New-Object System.Collections.Generic.List[string]
 625:     if ($RevBefore.tree_sha256 -ne $RevAfter.tree_sha256) {
 626:         $paths = Get-ManifestChanges -Before $RevBefore.manifest -After $RevAfter.manifest
 627:         $why.Add("the working tree changed during the run (by the reviewer or anyone else): $(& $cut $paths)")
 628:     }
 629:     $collab = Compare-DirectorySnapshot -Before $CollabBefore -After $CollabAfter -IgnorePrefixes $OwnPrefixes
 630:     if ($collab.Count -gt 0) { $why.Add("the collab directory changed during the run (by the reviewer or anyone else): $(& $cut ([string[]]@($collab | ForEach-Object { $CollabShown + $_ })))") }
 631:     if ($BriefChanged) { $why.Add('the brief changed during the run (by the reviewer or anyone else)') }
 632:     if (@($ChangedArtifacts).Count -gt 0) { $why.Add("artifact(s) changed during the run (by the reviewer or anyone else): $(@($ChangedArtifacts) -join ', ')") }
 633:     if ($why.Count -eq 0) { return '' }
 634:     return (($why.ToArray() -join '; ') + " - $Engine's sandbox does not block writes")
 635: }
