603:             }
604:         }
605:     }
606:     $watch.Stop()
607:     $t.Wall = [math]::Round($watch.Elapsed.TotalSeconds, 1)
608:     $t.Stderr = Read-SharedText -Path $StderrPath
609:     return $t
610: }
