3908:     if ($p -ieq 'none') { return [pscustomobject]@{ Path = ''; FromEnv = $true; Disabled = $true } }
3909:     if ($p) {
3910:         if (-not [IO.Path]::IsPathRooted($p)) { $p = Join-Path (Get-Location).Path $p }
3911:         return [pscustomobject]@{ Path = $p; FromEnv = $true; Disabled = $false }
3912:     }
3913:     $codexHome = Get-CodexHome
3914:     $default = ''
3915:     if ($codexHome) { $default = Join-Path $codexHome 'codex-consult-roster.json' }
3916:     return [pscustomobject]@{ Path = $default; FromEnv = $false; Disabled = $false }
3917: }
