3186: $script:UuidRe = '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
3187: 
3188: # One agy event stream (stdout of --output-format stream-json), parsed tolerantly into the
3189: # normalized turn record the run block uses:
3190: #   InitThread       init.conversation_id ('' when none)
3191: #   ResultCount      number of `result` events (exactly one is a well-formed stream)
3192: #   Malformed        '' or why the stream is malformed: a line that does not parse, more
3193: #                    than one result, a result that is not an object. The LAST non-empty
3194: #                    line may be a partial line only with -AllowPartialLast - the caller
3195: #                    passes it when the process was killed (timeout) or exited non-zero
3196: #                    (wave 18, F10-2); on exit 0 trailing garbage makes the stream malformed
3197: #   HasResult        a result event was seen
3198: #   Thread           result.conversation_id ('' when absent)
3199: #   Status, Response, Error      result.status / .response / .error (strings)
3200: #   HasStructured    result.structured_output is a JSON object
3201: #   StructuredJson   that object serialized compactly (ConvertTo-Json -Compress -Depth 30)
3202: #   Usage            { input_tokens, cached_input_tokens (cache_read_tokens), output_tokens,
3203: #                    reasoning_output_tokens (thinking_tokens), total_tokens } or $null
3204: #   ToolName         tool_name of the LAST step_update with step_type "tool" ('' when none)
3205: #   DeniedAction     result.denied_actions[].display_name / .action (first; '' when none)
3206: function Read-AgyEvents {
3207:     param([string]$Path, [switch]$AllowPartialLast)
3208:     $r = [pscustomobject]@{ InitThread = ''; ResultCount = 0; Malformed = ''; HasResult = $false; Thread = ''; Status = ''; Response = ''; Error = ''; HasStructured = $false; StructuredJson = ''; Usage = $null; ToolName = ''; DeniedAction = '' }
3209:     $text = Read-SharedText -Path $Path
3210:     if (-not $text) { return $r }
3211:     $lines = @($text -split "`r?`n")
3212:     $lastIdx = -1
3213:     for ($i = $lines.Count - 1; $i -ge 0; $i--) { if ($lines[$i].Trim()) { $lastIdx = $i; break } }
3214:     $result = $null
3215:     for ($i = 0; $i -lt $lines.Count; $i++) {
3216:         $t = $lines[$i].Trim()
3217:         if (-not $t) { continue }
3218:         $obj = $null
3219:         try { $obj = ConvertFrom-Json -InputObject $t } catch { $obj = $null }
3220:         if ($null -eq $obj -or -not ($obj -is [System.Management.Automation.PSCustomObject])) {
3221:             if (($i -ne $lastIdx -or -not $AllowPartialLast) -and -not $r.Malformed) { $r.Malformed = "line $($i + 1) is not a JSON object" }
3222:             continue
3223:         }
3224:         $ev = [string](Get-PropertyValue $obj 'event' '')
3225:         if ($ev -eq 'init') {
3226:             if (-not $r.InitThread) { $r.InitThread = [string](Get-PropertyValue $obj 'conversation_id' '') }
3227:         } elseif ($ev -eq 'step_update') {
3228:             $su = Get-PropertyValue $obj 'step_update' $null
3229:             if ($su -and [string](Get-PropertyValue $su 'step_type' '') -eq 'tool') {
3230:                 $tn = [string](Get-PropertyValue $su 'tool_name' '')
3231:                 if ($tn) { $r.ToolName = $tn }
3232:             }
3233:         } elseif ($ev -eq 'result') {
3234:             $r.ResultCount++
3235:             $res = Get-PropertyValue $obj 'result' $null
3236:             if ($null -eq $res -or -not ($res -is [System.Management.Automation.PSCustomObject])) {
3237:                 if (-not $r.Malformed) { $r.Malformed = "result event at line $($i + 1) is not an object" }
3238:                 continue
3239:             }
3240:             $result = $res
3241:         }
3242:     }
3243:     if ($r.ResultCount -gt 1 -and -not $r.Malformed) { $r.Malformed = "$($r.ResultCount) result events (exactly one expected)" }
3244:     if ($null -ne $result) {
3245:         $r.HasResult = $true
3246:         $r.Thread = [string](Get-PropertyValue $result 'conversation_id' '')
3247:         $r.Status = [string](Get-PropertyValue $result 'status' '')
3248:         $r.Response = [string](Get-PropertyValue $result 'response' '')
3249:         $err = Get-PropertyValue $result 'error' ''
3250:         if ($err -is [string]) { $r.Error = $err } else { $r.Error = (ConvertTo-Json -InputObject $err -Compress -Depth 10) }
3251:         $so = Get-PropertyValue $result 'structured_output' $null
3252:         if ($null -ne $so -and $so -is [System.Management.Automation.PSCustomObject]) {
3253:             $r.HasStructured = $true
3254:             $r.StructuredJson = ConvertTo-Json -InputObject $so -Compress -Depth 30
3255:         }
3256:         $u = Get-PropertyValue $result 'usage' $null
3257:         if ($null -ne $u) {
3258:             $map = [ordered]@{ input_tokens = 'input_tokens'; cached_input_tokens = 'cache_read_tokens'; output_tokens = 'output_tokens'; reasoning_output_tokens = 'thinking_tokens'; total_tokens = 'total_tokens' }
3259:             $values = [ordered]@{}
3260:             foreach ($k in $map.Keys) {
3261:                 $values[$k] = $null
3262:                 $v = Get-PropertyValue $u $map[$k] $null
3263:                 $n = [long]0
3264:                 if ($null -ne $v -and [long]::TryParse([string]$v, [ref]$n)) { $values[$k] = $n }
3265:             }
3266:             $r.Usage = [pscustomobject]$values
3267:         }
3268:         foreach ($da in @(Get-PropertyValue $result 'denied_actions' @())) {
3269:             if ($null -eq $da) { continue }
3270:             $name = [string](Get-PropertyValue $da 'display_name' '')
3271:             if (-not $name) { $name = [string](Get-PropertyValue $da 'action' '') }
3272:             if ($name) { $r.DeniedAction = $name; break }
3273:         }
3274:     }
3275:     return $r
3276: }
