3278: # The failure rules of one agy turn (the main turn, a denial retry, a format repair):
3279: # { Ok; Outcome ('usable reply' | 'failed: ...'); Class ('' = classify the texts, else the
3280: # forced provider_failure class); Texts (the failure evidence, best first); Thread (a verified
3281: # conversation id, '' otherwise); ThreadCandidate (an id that is never a parent); Reply (the
3282: # reply text: structured_output serialized, else the response); Structured; DeniedEmpty (the
3283: # F11 case: a denial notice and nothing to use); DenialLine; Permission (the permission the
3284: # notice names, e.g. command); NotFound (the resume warning line); Warnings (string[]) }.
3285: #   $Pre             a failure the bridge already knows (timeout, could not start, not
3286: #                    registered) - it wins
3287: #   exit != 0        failed: agy exit <n> - <result.error | stderr>
3288: #   malformed        failed: malformed event stream: <why> (class transport)
3289: #   no result        failed: no result event in the agy event stream (init id -> candidate)
3290: #   init != result   failed: conversation id mismatch (class unknown)
3291: #   status           failed: agy status <S> - <error>
3292: #   $ExpectThread    (resume, repair, denial retry) the not-found warning, a result without
3293: #                    conversation_id, or another id -> failed (class unknown); the new id is
3294: #                    a candidate only
3295: #   not a uuid       failed (class unknown)
3296: #   partial          stderr "returning partial output" / "print timeout" -> failed
3297: #   empty reply      with a denial notice: failed: <notice> (class permission, DeniedEmpty);
3298: #                    otherwise failed: empty reply
3299: #   usable           a denial notice and every `warning:` line of stderr become Warnings
3300: function Get-AgyTurnOutcome {
3301:     param($Events, [int]$ExitCode, [string]$StderrText = '', [string]$Pre = '', [string]$ExpectThread = '')
3302:     $o = [pscustomobject]@{ Ok = $false; Outcome = ''; Class = ''; Texts = [string[]]@(); Thread = ''; ThreadCandidate = ''; Reply = ''; Structured = $false; DeniedEmpty = $false; DenialLine = ''; Permission = ''; NotFound = ''; Warnings = [string[]]@() }
3303:     $lines = @(([string]$StderrText) -split "`r?`n" | ForEach-Object { $_.Trim() } | Where-Object { $_ })
3304:     $denial = @($lines | Where-Object { $_ -match '(?i)no output produced|auto-denied' }) | Select-Object -First 1
3305:     $notFound = @($lines | Where-Object { $_ -match '(?i)^warning:\s*conversation\s.*not found' }) | Select-Object -First 1
3306:     $partial = @($lines | Where-Object { $_ -match '(?i)returning partial output|print timeout' }) | Select-Object -First 1
3307:     $warnLines = @($lines | Where-Object { $_ -match '(?i)^warning:' })
3308:     $stderrTail = if ($lines.Count -gt 0) { $lines[-1] } else { '' }
3309:     if ($denial) {
3310:         $o.DenialLine = [string]$denial
3311:         if ($denial -match 'the "(?<perm>[^"]+)" permission') { $o.Permission = $Matches['perm'] }
3312:     }
3313:     if ($notFound) { $o.NotFound = [string]$notFound }
3314:     $o.Reply = if ($Events.HasStructured) { [string]$Events.StructuredJson } else { [string]$Events.Response }
3315:     $o.Structured = [bool]$Events.HasStructured
3316:     $resId = [string]$Events.Thread
3317:     $initId = [string]$Events.InitThread
3318:     $fail = {
3319:         param([string]$Why, [string]$Class = '', [string[]]$Texts = @())
3320:         $o.Ok = $false
3321:         $o.Outcome = "failed: $Why"
3322:         $o.Class = $Class
3323:         $o.Texts = [string[]]@(@($Texts) + @($Why) | Where-Object { $_ })
3324:     }
3325:     $bestErr = [string]$Events.Error
3326:     $detail = if ($bestErr) { $bestErr } elseif ($denial) { [string]$denial } else { $stderrTail }
3327:     if ($Pre) {
3328:         $o.Outcome = $Pre
3329:         $o.Texts = [string[]]@(@($bestErr, $detail, ($Pre -replace '^failed:\s*', '')) | Where-Object { $_ })
3330:         if ($resId -match $script:UuidRe) { $o.ThreadCandidate = $resId } elseif ($initId -match $script:UuidRe) { $o.ThreadCandidate = $initId }
3331:         return $o
3332:     }
3333:     if ($ExitCode -ne 0) {
3334:         & $fail "agy exit $ExitCode$(if ($detail) { " - $(ConvertTo-OneLine $detail)" })" '' @($bestErr, $detail)
3335:         if ($resId -match $script:UuidRe -and (-not $ExpectThread -or $resId -eq $ExpectThread) -and -not $notFound) { $o.Thread = $resId } elseif ($resId -match $script:UuidRe) { $o.ThreadCandidate = $resId } elseif ($initId -match $script:UuidRe) { $o.ThreadCandidate = $initId }
3336:         return $o
3337:     }
3338:     if ($Events.Malformed) {
3339:         & $fail "malformed event stream: $($Events.Malformed)" 'transport'
3340:         if ($initId -match $script:UuidRe) { $o.ThreadCandidate = $initId }
3341:         return $o
3342:     }
3343:     if (-not $Events.HasResult) {
3344:         & $fail "no result event in the agy event stream$(if ($stderrTail) { " - $(ConvertTo-OneLine $stderrTail)" })" '' @($stderrTail)
3345:         if ($initId -match $script:UuidRe) { $o.ThreadCandidate = $initId }
3346:         return $o
3347:     }
3348:     if ($initId -and $resId -and $initId -ne $resId) {
3349:         & $fail "conversation id mismatch: init $initId, result $resId" 'unknown'
3350:         if ($resId -match $script:UuidRe) { $o.ThreadCandidate = $resId }
3351:         return $o
3352:     }
3353:     if ($ExpectThread) {
3354:         if ($notFound) {
3355:             & $fail "parent conversation $ExpectThread not found, agy started $(if ($resId) { $resId } else { 'another conversation' }) ($notFound)" 'unknown' @($notFound)
3356:             if ($resId -match $script:UuidRe) { $o.ThreadCandidate = $resId }
3357:             return $o
3358:         }
3359:         if (-not $resId) {
3360:             & $fail "the result names no conversation id (resume of $ExpectThread)" 'unknown'
3361:             return $o
3362:         }
3363:         if ($resId -ne $ExpectThread) {
3364:             & $fail "parent conversation $ExpectThread not found, agy started $resId" 'unknown'
3365:             if ($resId -match $script:UuidRe) { $o.ThreadCandidate = $resId }
3366:             return $o
3367:         }
3368:     }
3369:     if ($Events.Status -ne 'SUCCESS') {
3370:         & $fail "agy status $(if ($Events.Status) { $Events.Status } else { '(none)' })$(if ($detail) { " - $(ConvertTo-OneLine $detail)" })" '' @($bestErr, $detail)
3371:         if ($resId -match $script:UuidRe) { $o.Thread = $resId }
3372:         return $o
3373:     }
3374:     if (-not ($resId -match $script:UuidRe)) {
3375:         & $fail "the result's conversation_id '$resId' is not a uuid" 'unknown'
3376:         return $o
3377:     }
3378:     $o.Thread = $resId
3379:     if ($partial) {
3380:         & $fail "partial output - $(ConvertTo-OneLine $partial)" '' @($partial)
3381:         return $o
3382:     }
3383:     if (-not $Events.HasStructured -and -not ([string]$Events.Response).Trim()) {
3384:         if ($denial) {
3385:             & $fail (ConvertTo-OneLine $denial) 'permission' @($denial)
3386:             $o.DeniedEmpty = $true
3387:         } else {
3388:             & $fail "empty reply$(if ($bestErr) { " - $(ConvertTo-OneLine $bestErr)" })" '' @($bestErr)
3389:         }
3390:         return $o
3391:     }
3392:     $o.Ok = $true
3393:     $o.Outcome = 'usable reply'
3394:     $w = New-Object System.Collections.Generic.List[string]
3395:     if ($denial) { $w.Add("denial notice: $(ConvertTo-OneLine $denial)") }
3396:     foreach ($wl in $warnLines) { $w.Add((ConvertTo-OneLine $wl)) }
3397:     $o.Warnings = [string[]]$w.ToArray()
3398:     return $o
