3684: # The ledger's provider_failure of a failed run: { class; code; message (<= 200); when;
3685: # retry_after }. $Texts: the evidence in order of preference (the event-stream error,
3686: # stderr, the bridge outcome); the first that holds a provider error payload wins, else the
3687: # first non-empty. retry_after: the reset time the chosen message names (Get-RetryAfter,
3688: # read from the FULL message before it is cut to 200 characters), ISO with offset, or $null.
3689: function New-ProviderFailure {
3690:     param([string[]]$Texts, [string]$Class = '')
3691:     $chosen = $null
3692:     $chosenRaw = ''
3693:     foreach ($t in @($Texts | Where-Object { $_ -and $_.Trim() })) {
3694:         $p = ConvertFrom-ProviderErrorText -Text $t
3695:         if ($p.Code -or ($t.IndexOf('{"error"') -ge 0)) { $chosen = $p; $chosenRaw = $t; break }
3696:         if (-not $chosen) { $chosen = $p; $chosenRaw = $t }
3697:     }
3698:     if (-not $chosen) { $chosen = [pscustomobject]@{ Code = ''; Message = '' } }
3699:     $msg = [string]$chosen.Message
3700:     $now = Get-Date
3701:     $retryAfter = Get-RetryAfter -Message $msg -Reference ([DateTimeOffset]$now)
3702:     # A gRPC error payload (Google, the agy engine) names its reset time in the details
3703:     # (RetryInfo.retryDelay), outside error.message.
3704:     if ($null -eq $retryAfter -and $chosenRaw -and $chosenRaw -match '(?i)retryDelay') { $retryAfter = Get-RetryAfter -Message $chosenRaw -Reference ([DateTimeOffset]$now) }
3705:     if ($msg.Length -gt 200) { $msg = $msg.Substring(0, 200) }
3706:     return [pscustomobject]@{
3707:         class       = $(if ($Class) { $Class } else { (Get-ProviderFailureClass "$($chosen.Code) $($chosen.Message)") })
3708:         code        = [string]$chosen.Code
3709:         message     = $msg
3710:         when        = (Get-IsoTimestamp $now)
3711:         retry_after = $(if ($null -ne $retryAfter) { Format-OffsetIso $retryAfter } else { $null })
3712:     }
3713: }
