1135: # Contextual checks of a structurally valid (normalized) reply:
1136: #   * the verdict must fit the purpose: ACCEPT|HOLD|REJECT for acceptance and
1137: #     diff-review, ADVISE for every other purpose and for none;
1138: #   * ACCEPT contradicts any NEW blocker finding;
1139: #   * ACCEPT contradicts an open prior blocker the reply reports still-open;
1140: #   * ACCEPT with an open prior blocker reported not-checked (or not reported) is
1141: #     allowed but returned in Unchecked so the caller can warn.
1142: function Test-ReplySemantics {
1143:     param($Reply, [string]$Purpose = '', $PriorFindings = @())
1144:     $problems = New-Object System.Collections.Generic.List[string]
1145:     $short = New-Object System.Collections.Generic.List[string]
1146:     $unchecked = @()
1147:     $verdict = [string]$Reply.verdict
1148:     $allowed = Get-AllowedVerdicts -Purpose $Purpose
1149:     $purposeLabel = if ($Purpose) { $Purpose } else { 'none' }
1150:     if ($allowed -cnotcontains $verdict) {
1151:         $problems.Add("verdict $verdict is not allowed for purpose $purposeLabel (expected $($allowed -join '|'))")
1152:         $short.Add("$verdict not allowed for purpose $purposeLabel")
1153:     }
1154:     if ($verdict -eq 'ACCEPT') {
1155:         $newBlockers = @($Reply.findings | Where-Object { $_.severity -eq 'blocker' }).Count
1156:         if ($newBlockers -gt 0) {
1157:             $problems.Add("verdict ACCEPT contradicts $newBlockers blocker finding(s)")
1158:             $short.Add("ACCEPT contradicts $newBlockers blocker")
1159:         }
1160:         $dispositions = @(Get-PriorBlockerDispositions -Reply $Reply -PriorFindings $PriorFindings)
1161:         $stillOpen = @($dispositions | Where-Object { $_.disposition -eq 'still-open' } | ForEach-Object { $_.id })
1162:         if ($stillOpen.Count -gt 0) {
1163:             $problems.Add("verdict ACCEPT contradicts still-open prior blocker $($stillOpen -join ', ')")
1164:             $short.Add("ACCEPT contradicts still-open prior blocker $($stillOpen -join ', ')")
1165:         }
1166:         $unchecked = @($dispositions | Where-Object { $_.disposition -eq 'not-checked' } | ForEach-Object { $_.id })
1167:     }
1168:     return [pscustomobject]@{
1169:         Problems  = [string[]]$problems.ToArray()
1170:         Short     = [string[]]$short.ToArray()
1171:         Unchecked = [string[]]$unchecked
1172:     }
1173: }
