 75: $stdinText = $u8.GetString($stdinBytes)
 76: $conv = ''
 77: if ($raw -match '--conversation\s+(\S+)') { $conv = $Matches[1] }
 78: $model = 'unknown'
 79: if ($raw -match '--model\s+(\S+)') { $model = $Matches[1] }
 80: $log = if ($conv -and $env:FAKE_AGY_RESUME_LOG) { $env:FAKE_AGY_RESUME_LOG } elseif (-not $conv) { $env:FAKE_AGY_LOG } else { '' }
 81: # (retried on a sharing violation: the members of a parallel panel share the harness's variables)
 82: function Invoke-FakeWrite { param([scriptblock]$Do) for ($i = 0; $i -lt 40; $i++) { try { & $Do; return } catch { Start-Sleep -Milliseconds 50 } }; & $Do }
 83: if ($log) {
 84:     Invoke-FakeWrite { [IO.File]::WriteAllText($log, "ARGS: $raw`nSTDIN:`n$stdinText", $u8) }
 85:     Invoke-FakeWrite { [IO.File]::WriteAllBytes("$log.stdin", $stdinBytes) }
 86: }
 87: if ($env:FAKE_AGY_PIDFILE) { Invoke-FakeWrite { [IO.File]::WriteAllText($env:FAKE_AGY_PIDFILE, "$PID") } }
 88: 
 89: $cmode = [string]$env:FAKE_AGY_CONVERSATION
 90: $id = [guid]::NewGuid().ToString()
 91: if ($conv) {
 92:     if ($cmode -eq 'notfound') { Err-Bytes "warning: conversation `"$conv`" not found" }
 93:     elseif ($cmode -ne 'other') { $id = $conv }
 94: }
 95: if ($cmode -eq 'notuuid') { $id = 'conv-1' }
 96: $resultId = $id
 97: if ($cmode -eq 'mismatch') { $resultId = [guid]::NewGuid().ToString() }
 98: 
 99: $denied = ($env:FAKE_AGY_DENIED -eq 'all') -or ($env:FAKE_AGY_DENIED -eq '1' -and -not $conv)
100: Out-Bytes ((J ([pscustomobject]@{ event = 'init'; conversation_id = $id; init = [pscustomobject]@{ model = $model; cwd = (Get-Location).Path; tools = @('view_file', 'grep_search', 'run_command', 'write_to_file'); permission_mode = 'request-review' } })) + "`n")
101: Out-Bytes ((J ([pscustomobject]@{ event = 'step_update'; step_update = [pscustomobject]@{ conversation_id = $id; step_index = 0; state = 'DONE'; step_type = 'user_input' } })) + "`n")
102: if ($env:FAKE_AGY_HANG -eq '1' -or ($env:FAKE_AGY_HANG_ON -and $raw.Contains($env:FAKE_AGY_HANG_ON))) { Start-Sleep -Seconds 60 }
103: Out-Bytes ((J ([pscustomobject]@{ event = 'step_update'; step_update = [pscustomobject]@{ conversation_id = $id; step_index = 1; state = 'DONE'; step_type = 'tool'; tool_name = 'view_file'; duration_seconds = 0.1; tool_info = [pscustomobject]@{ name = 'view_file'; parameters = [pscustomobject]@{ AbsolutePath = 'app.txt' }; output = '1 lines' } } })) + "`n")
104: $delayMs = $null
105: if ($env:FAKE_AGY_DELAY_MS) {
106:     foreach ($item in $env:FAKE_AGY_DELAY_MS.Split('|')) {
107:         $eq = $item.IndexOf('=')
108:         if ($eq -lt 0) { if ($item.Trim() -and $null -eq $delayMs) { $delayMs = $item.Trim() }; continue }
109:         $k = $item.Substring(0, $eq).Trim()
110:         if ($k -ceq $model) { $delayMs = $item.Substring($eq + 1).Trim(); break }
111:         if ($k -eq '*') { $delayMs = $item.Substring($eq + 1).Trim() }
112:     }
113: }
114: if ($delayMs) { Start-Sleep -Milliseconds ([int]$delayMs) }
115: if ($env:FAKE_AGY_WRITE) {
116:     $w = $env:FAKE_AGY_WRITE.Split('|')
117:     if (-not $conv -or ($w.Count -gt 1 -and $w[1] -eq 'all')) {
118:         $target = Join-Path (Get-Location).Path $w[0]
119:         [void][IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($target))
120:         [IO.File]::WriteAllText($target, "written by the fake agy`n", $u8)
121:     }
122: }
123: if ($denied) {
124:     Out-Bytes ((J ([pscustomobject]@{ event = 'step_update'; step_update = [pscustomobject]@{ conversation_id = $id; step_index = 2; state = 'ACTIVE'; step_type = 'tool'; tool_name = 'run_command'; tool_info = [pscustomobject]@{ name = 'run_command'; parameters = [pscustomobject]@{ CommandLine = 'agy --version' } } } })) + "`n")
125:     Out-Bytes ((J ([pscustomobject]@{ event = 'step_update'; step_update = [pscustomobject]@{ conversation_id = $id; step_index = 2; state = 'DONE'; step_type = 'tool'; tool_name = 'run_command'; duration_seconds = 0.3 } })) + "`n")
126:     Err-Bytes ('jetski: no output produced ' + [char]0x2014 + ' a tool required the "command" permission that headless mode cannot prompt for, so it was auto-denied. Add an allow-rule under permissions.allow in settings.json (e.g. command(<target>)). Alternatively, re-run with --dangerously-skip-permissions to auto-approve all tools.')
127: }
128: if ($env:FAKE_AGY_PARTIAL -eq '1') { Err-Bytes '[agy] print timeout after 20s with turn in progress; returning partial output' }
129: if ($env:FAKE_AGY_STDERR) { Err-Bytes $env:FAKE_AGY_STDERR }
130: if ($env:FAKE_AGY_BADLINE -eq '1') { Out-Bytes "this is not json`n" }
131: 
132: # the reply
133: $replyFile = $env:FAKE_AGY_REPLY
134: $fromResume = $false
135: if ($conv -and $env:FAKE_AGY_RESUME_REPLY) { $replyFile = $env:FAKE_AGY_RESUME_REPLY; $fromResume = $true }
136: $response = ''
137: $structured = $null
138: if ($replyFile -and -not ($denied -and $env:FAKE_AGY_DENIED_REPLY -ne '1') -and $env:FAKE_AGY_PARTIAL -ne '1') {
139:     $text = [IO.File]::ReadAllText($replyFile, $u8)
140:     $obj = $null
141:     if (-not ($env:FAKE_AGY_NOSTRUCTURED -eq '1' -and -not $fromResume)) { try { $obj = ConvertFrom-Json -InputObject $text } catch { $obj = $null } }
142:     if ($null -ne $obj -and $obj -is [System.Management.Automation.PSCustomObject]) {
143:         $structured = $obj
144:         # F4: the response text of the same run is NOT the object (two extra keys)
145:         $withExtra = ConvertFrom-Json -InputObject $text
146:         $withExtra | Add-Member -NotePropertyName 'toolAction' -NotePropertyValue 'finish' -Force
147:         $withExtra | Add-Member -NotePropertyName 'toolSummary' -NotePropertyValue 'done' -Force
148:         $response = J $withExtra
149:     } else {
150:         $response = $text
151:     }
152: }
153: Out-Bytes ((J ([pscustomobject]@{ event = 'step_update'; step_update = [pscustomobject]@{ conversation_id = $id; step_index = 3; state = 'DONE'; step_type = 'agent_response'; duration_seconds = 1.5; usage = [pscustomobject]@{ input_tokens = 9000; output_tokens = 400; thinking_tokens = 100; cache_read_tokens = 0; total_tokens = 9400 } } })) + "`n")
154: if ($env:FAKE_AGY_NORESULT -ne '1') {
155:     $status = if ($env:FAKE_AGY_STATUS) { $env:FAKE_AGY_STATUS } else { 'SUCCESS' }
156:     $usage = if ($conv) { [pscustomobject]@{ input_tokens = 54000; output_tokens = 300; thinking_tokens = 80; cache_read_tokens = 30000; total_tokens = 54300 } } else { [pscustomobject]@{ input_tokens = 13000; output_tokens = 500; thinking_tokens = 120; cache_read_tokens = 4000; total_tokens = 13500 } }
157:     $res = [ordered]@{ conversation_id = $resultId; status = $status; response = $response; duration_seconds = 3.1; num_turns = 1 }
158:     if ($null -ne $structured) { $res['structured_output'] = $structured }
159:     if ($env:FAKE_AGY_ERROR) { $res['error'] = $env:FAKE_AGY_ERROR }
160:     $res['usage'] = $usage
161:     if ($denied) { $res['denied_actions'] = [pscustomobject]@{ action = 'command'; display_name = 'RunCommand' } }
162:     $line = (J ([pscustomobject]@{ event = 'result'; result = [pscustomobject]$res })) + "`n"
163:     Out-Bytes $line
164:     if ($env:FAKE_AGY_TWORESULTS -eq '1') { Out-Bytes $line }
165: }
166: if ($env:FAKE_AGY_TRAILING) { Out-Bytes $env:FAKE_AGY_TRAILING }
167: if ($env:FAKE_AGY_HANG_AFTER -eq '1') { Start-Sleep -Seconds 60 }
168: if ($env:FAKE_AGY_EXIT) { exit ([int]$env:FAKE_AGY_EXIT) }
169: if ($env:FAKE_AGY_STATUS -and $env:FAKE_AGY_STATUS -ne 'SUCCESS') { exit 1 }
170: exit 0
